// Package chainledger implements the on-chain data governance core.
//
// This file adds local lineage snapshots: a snapshot freezes one graph as a
// versioned, content-addressed JSON document, and two snapshots can be compared
// read-only. Every byte a snapshot writes is determined solely by the graph's
// semantics — dataset names and their direct upstreams — never by record
// order, upstream order, duplicate upstreams, JSON whitespace, save time, or
// file path.
package chainledger

import (
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"sort"
)

// SnapshotFormatVersion is the only on-disk snapshot format understood.
const SnapshotFormatVersion = 1

// SnapshotFile is the on-disk representation of one frozen lineage graph.
//
// FormatVersion is fixed at 1. ContentID addresses the graph semantics and is
// verified against Graph on every read; Graph carries the complete graph.
type SnapshotFile struct {
	FormatVersion int       `json:"formatVersion"`
	ContentID     string    `json:"contentId"`
	Graph         GraphFile `json:"graph"`
}

// RootSourceChange reports that one dataset present in BOTH versions reaches a
// different set of root sources. OldRoots and NewRoots are sorted by name and
// never nil, so empty root sets encode as [] rather than null.
type RootSourceChange struct {
	Dataset  string   `json:"dataset"`
	OldRoots []string `json:"oldRoots"`
	NewRoots []string `json:"newRoots"`
}

// CompareReport is the deterministic, read-only diff of two snapshots read in
// the fixed direction old -> new.
//
// NewDatasets and RemovedDatasets list nodes present on only one side.
// ChangedDatasets lists datasets present on both sides whose direct upstream
// set actually changed. AddedRelations and RemovedRelations list every
// directed edge present on only one side, including edges that vanish because
// one endpoint node was removed. RootSourceChanges covers only datasets common
// to both versions whose reachable root set differs; added or removed datasets
// never appear there.
type CompareReport struct {
	NewDatasets       []string           `json:"newDatasets"`
	RemovedDatasets   []string           `json:"removedDatasets"`
	ChangedDatasets   []string           `json:"changedDatasets"`
	AddedRelations    []Relation         `json:"addedRelations"`
	RemovedRelations  []Relation         `json:"removedRelations"`
	RootSourceChanges []RootSourceChange `json:"rootSourceChanges"`
}

// contentIDPrefix names the hash algorithm used for content addressing.
const contentIDPrefix = "sha256:"

// canonicalGraph serializes the graph's semantics deterministically: datasets
// sorted by name byte order with sorted, duplicate-free upstream lists, compact
// JSON with no insignificant whitespace. Two semantically equal graphs always
// produce identical bytes.
func canonicalGraph(adj adjacency) ([]byte, error) {
	gf := GraphFile{Datasets: adjacencyToDatasets(adj)}
	return json.Marshal(gf)
}

// computeContentID returns the content identifier of the graph bytes:
// "sha256:" followed by the lowercase hex SHA-256 digest.
func computeContentID(canonical []byte) string {
	sum := sha256.Sum256(canonical)
	return contentIDPrefix + hex.EncodeToString(sum[:])
}

// BuildSnapshot validates graph and freezes it into a SnapshotFile with format
// version 1 and the matching content identifier. It does not mutate graph. The
// returned document and its serialized bytes depend only on graph semantics.
//
// A dataset name or direct upstream reference that is not valid UTF-8 rejects
// the build with no snapshot and no content identifier: such bytes could not be
// serialized without silently rewriting the name, so the frozen document would
// not be a faithful, readable copy of the graph.
func BuildSnapshot(graph map[string]*Lineage) (*SnapshotFile, error) {
	// One read of the existing graph settles its legality and yields the
	// canonical relations the snapshot freezes — the same shared judgment
	// ValidateGraph, preview, apply, and graph export make.
	adj, err := validatedGraphAdjacency(graph)
	if err != nil {
		return nil, err
	}
	canonical, err := canonicalGraph(adj)
	if err != nil {
		return nil, err
	}
	return &SnapshotFile{
		FormatVersion: SnapshotFormatVersion,
		ContentID:     computeContentID(canonical),
		Graph:         GraphFile{Datasets: adjacencyToDatasets(adj)},
	}, nil
}

// MarshalSnapshot serializes a snapshot the same way for every save: indented
// JSON keyed by struct field order, terminated by a single newline.
func MarshalSnapshot(snap *SnapshotFile) ([]byte, error) {
	var buf bytes.Buffer
	enc := json.NewEncoder(&buf)
	enc.SetIndent("", "  ")
	enc.SetEscapeHTML(false)
	if err := enc.Encode(snap); err != nil {
		return nil, err
	}
	return buf.Bytes(), nil
}

// rawSnapshot mirrors SnapshotFile but keeps each field raw so ParseSnapshot
// can distinguish "field absent" from "field present with a zero value"
// (e.g. a missing formatVersion must be rejected rather than read as 0).
type rawSnapshot struct {
	FormatVersion json.RawMessage `json:"formatVersion"`
	ContentID     json.RawMessage `json:"contentId"`
	Graph         json.RawMessage `json:"graph"`
}

// isJSONNull reports whether a raw JSON value is the literal null.
func isJSONNull(raw json.RawMessage) bool {
	return string(bytes.TrimSpace(raw)) == "null"
}

// ParseSnapshot parses and strictly validates one snapshot document: required
// fields must be present and well-typed, no known field may be declared twice
// within the same object (even with identical values, a null first, or a
// spelling equivalent under Unicode case folding or JSON escaping), the
// format version must be supported, the embedded graph must be structurally
// valid (no empty names, duplicate datasets, missing upstreams, or cycles),
// and the content identifier must correspond exactly to the graph. A
// tampered, corrupt, or otherwise invalid snapshot is rejected, so a bad file
// can never be trusted as a version.
func ParseSnapshot(data []byte) (*SnapshotFile, error) {
	if err := checkDuplicateFields(data); err != nil {
		return nil, err
	}
	var raw rawSnapshot
	if err := json.Unmarshal(data, &raw); err != nil {
		return nil, fmt.Errorf("invalid snapshot JSON: %w", err)
	}
	if len(raw.FormatVersion) == 0 {
		return nil, fmt.Errorf("%w: snapshot is missing required field %q", ErrInvalidArgument, "formatVersion")
	}
	if len(raw.ContentID) == 0 {
		return nil, fmt.Errorf("%w: snapshot is missing required field %q", ErrInvalidArgument, "contentId")
	}
	if len(raw.Graph) == 0 {
		return nil, fmt.Errorf("%w: snapshot is missing required field %q", ErrInvalidArgument, "graph")
	}
	// An explicit JSON null is present-but-untyped and must not be silently
	// treated as a zero value (in particular, graph:null must not read as an
	// empty graph).
	if isJSONNull(raw.FormatVersion) {
		return nil, fmt.Errorf("%w: snapshot field %q must be a number, not null", ErrInvalidArgument, "formatVersion")
	}
	if isJSONNull(raw.ContentID) {
		return nil, fmt.Errorf("%w: snapshot field %q must be a string, not null", ErrInvalidArgument, "contentId")
	}
	if isJSONNull(raw.Graph) {
		return nil, fmt.Errorf("%w: snapshot field %q must be an object, not null", ErrInvalidArgument, "graph")
	}

	var version int
	if err := json.Unmarshal(raw.FormatVersion, &version); err != nil {
		return nil, fmt.Errorf("%w: snapshot field %q must be a number: %v", ErrInvalidArgument, "formatVersion", err)
	}
	if version != SnapshotFormatVersion {
		return nil, fmt.Errorf("%w: unsupported snapshot format version %d, supported version is %d", ErrInvalidArgument, version, SnapshotFormatVersion)
	}

	var contentID string
	if err := json.Unmarshal(raw.ContentID, &contentID); err != nil {
		return nil, fmt.Errorf("%w: snapshot field %q must be a string", ErrInvalidArgument, "contentId")
	}
	if contentID == "" {
		return nil, fmt.Errorf("%w: snapshot field %q must not be empty", ErrInvalidArgument, "contentId")
	}

	var gf GraphFile
	// The embedded graph obeys exactly the same name-encoding rule as a
	// standalone graph file: a raw name literal with invalid UTF-8 bytes or an
	// unpaired surrogate escape would be silently rewritten to U+FFFD, and a
	// corrupted upstream could then resolve to a genuinely different dataset.
	// The check runs on the graph's raw bytes and rejects the whole snapshot
	// even when the declared content identifier happens to match the
	// rewritten graph's digest. The raw scan is the shared one in
	// name_encoding.go applied to the graph document scope.
	if err := checkGraphNameEncoding(raw.Graph); err != nil {
		return nil, err
	}
	if err := json.Unmarshal(raw.Graph, &gf); err != nil {
		return nil, fmt.Errorf("invalid graph in snapshot: %w", err)
	}
	// The embedded graph obeys exactly the same structural rules as a
	// standalone graph file, so the two readers can never judge one graph
	// differently.
	adj, err := validateGraphStructureFromFile(gf.Datasets)
	if err != nil {
		return nil, err
	}

	canonical, err := canonicalGraph(adj)
	if err != nil {
		return nil, err
	}
	if want := computeContentID(canonical); contentID != want {
		return nil, fmt.Errorf("%w: content identifier %q does not match the graph (expected %q); the snapshot was altered or corrupted", ErrInvalidArgument, contentID, want)
	}

	return &SnapshotFile{
		FormatVersion: version,
		ContentID:     contentID,
		Graph:         GraphFile{Datasets: adjacencyToDatasets(adj)},
	}, nil
}

// checkDuplicateFields applies the shared repeated-known-field rule (see
// duplicate_fields.go) to a snapshot, supplying the snapshot's own field
// scope and locations: formatVersion, contentId, and graph at the top level,
// datasets inside graph, and name and upstreams inside each dataset record.
// The embedded graph is scanned by the same checkGraphObject a standalone
// graph file uses, so the two readers can never judge one graph differently.
func checkDuplicateFields(data []byte) error {
	return runFieldScan(data, func(dec *json.Decoder) error {
		return checkObjectFields(dec, "at the top level of the snapshot", []knownField{
			{name: "formatVersion"},
			{name: "contentId"},
			{name: "graph", nested: func(dec *json.Decoder) error {
				return checkGraphObject(dec, `in "graph"`)
			}},
		})
	})
}

// CompareSnapshots returns the fixed-direction diff from old to new. Both
// inputs are assumed to have passed ParseSnapshot; the report is fully
// deterministic and identical for semantically identical comparisons.
func CompareSnapshots(oldSnap, newSnap *SnapshotFile) *CompareReport {
	oldAdj := adjacencyFromValidFile(oldSnap.Graph)
	newAdj := adjacencyFromValidFile(newSnap.Graph)

	// Dataset-level changes follow the shared old -> new rule the batch report
	// uses (see diffDatasets), so comparing two snapshots classifies new,
	// removed, and directly changed datasets exactly the way previewing or
	// applying the batch that turns one version into the other does.
	newNodes, removedNodes, changedNodes := diffDatasets(oldAdj, newAdj)

	added, removed := diffRelations(oldAdj, newAdj)

	common := make([]string, 0)
	for name := range oldAdj {
		if _, ok := newAdj[name]; ok {
			common = append(common, name)
		}
	}
	sort.Strings(common)

	rootChanges := make([]RootSourceChange, 0)
	for _, name := range common {
		oldRoots := rootSources(name, oldAdj)
		newRoots := rootSources(name, newAdj)
		if !stringSliceEqual(oldRoots, newRoots) {
			rootChanges = append(rootChanges, RootSourceChange{
				Dataset:  name,
				OldRoots: oldRoots,
				NewRoots: newRoots,
			})
		}
	}

	return &CompareReport{
		NewDatasets:       orEmptyStrings(newNodes),
		RemovedDatasets:   orEmptyStrings(removedNodes),
		ChangedDatasets:   orEmptyStrings(changedNodes),
		AddedRelations:    orEmptyRelations(added),
		RemovedRelations:  orEmptyRelations(removed),
		RootSourceChanges: rootChanges,
	}
}

// adjacencyFromValidFile builds normalized parent adjacency from an already
// validated graph file.
func adjacencyFromValidFile(gf GraphFile) adjacency {
	adj := make(adjacency, len(gf.Datasets))
	for _, ds := range gf.Datasets {
		adj[ds.Name] = uniqueSorted(ds.Upstreams)
	}
	return adj
}

// rootSources returns the root datasets reachable from node by following
// direct upstream edges. A node without upstreams is itself a root and its own
// source, so it is included. Nodes reached by more than one path count once.
// The result is sorted by name and never nil.
func rootSources(node string, adj adjacency) []string {
	visited := make(map[string]bool)
	var roots []string
	var walk func(string)
	walk = func(current string) {
		if visited[current] {
			return
		}
		visited[current] = true
		parents := adj[current]
		if len(parents) == 0 {
			roots = append(roots, current)
			return
		}
		for _, parent := range parents {
			walk(parent)
		}
	}
	walk(node)
	sort.Strings(roots)
	return orEmptyStrings(roots)
}

func orEmptyStrings(s []string) []string {
	if s == nil {
		return []string{}
	}
	return s
}

func orEmptyRelations(r []Relation) []Relation {
	if r == nil {
		return []Relation{}
	}
	return r
}

// Package chainledger guards every reader of lineage-bearing names against
// the same silent name substitution.
//
// encoding/json decodes every JSON string by replacing each invalid UTF-8
// byte — and each \u escape that is an unpaired surrogate — with U+FFFD, so
// the decoded document no longer names the datasets the file actually wrote.
// A corrupted reference can then collide with a real node: when one
// dataset's direct upstream is written as "源" plus one lone \uD800 escape,
// the decoder turns it into "源�" and the edge is silently accepted as a
// reference to the root dataset genuinely named "源�"; a corrupted removals
// entry could delete a dataset the user never named. The reader must not
// guess which dataset the file meant, so every name that takes part in
// lineage relations — each datasets[i].name and every
// datasets[i].upstreams[j] in a standalone graph file or in the graph
// embedded in a snapshot, and in a plan each changes[i].name, every
// changes[i].upstreams[j], and every removals[i] (even one that names a
// dataset that does not exist) — is checked against its RAW string literal
// before the document is accepted. A literal carrying bytes that are not
// valid UTF-8, or a \u escape forming an unpaired surrogate (a lone high or
// low surrogate, or a low surrogate written before its high surrogate),
// rejects the whole input: the decoder's rewrite is never kept, the
// offending node or edge is never skipped, and a snapshot whose declared
// content identifier happens to equal the rewritten graph's digest is still
// refused.
//
// Only the raw literal can tell corruption apart from a genuine name: the
// replacement character itself ("�", or the equivalent JSON escape) is legal
// and stays accepted, as is every correctly paired surrogate escape. Names
// that merely LOOK like escapes (a backslash followed by an ordinary letter,
// including a doubled backslash before "ud800") are plain text to JSON and
// are never rejected for that reason.
//
// This file is the single implementation of that rule, shared by the graph
// and plan document scopes in graph_name_encoding.go and
// plan_name_encoding.go. Field recognition is the reader's own — keys are
// compared after JSON unescaping with Unicode case folding via the shared
// walker in duplicate_fields.go (scanObjectFields/checkArrayElements) — so a
// field spelled "Name" is checked exactly like "name", unknown fields and
// everything nested inside them are skipped, and the graph and plan readers
// can never drift apart about which strings are names, how a record is read,
// or how an error is located. A document too malformed to walk is left to
// the regular parse, exactly as in duplicate_fields.go.
package chainledger

import (
	"encoding/json"
	"fmt"
	"unicode/utf8"
)

// graphNameFields is the field scope of one dataset record — the same shape
// whether the record sits in a graph's "datasets" array or in a plan's
// "changes" array — for the raw name-encoding scan: both its "name" string
// and every "upstreams" string element are lineage names and must each
// decode faithfully. Location wording is supplied per array field and
// record kind, so a dataset record and a change record judged at the same
// position fail with the same rule and only the document-specific nouns
// differ.
func graphNameFields(index int, arrayField, recordKind string) []knownField {
	return []knownField{
		{name: "name", nested: func(dec *json.Decoder) error {
			location := fmt.Sprintf("field %q in the %s at index %d of %q", "name", recordKind, index, arrayField)
			return checkNameStringEncoding(dec, location)
		}},
		{name: "upstreams", nested: func(dec *json.Decoder) error {
			return checkArrayElements(dec, func(dec *json.Decoder, item int) error {
				location := fmt.Sprintf("field %q at index %d in the %s at index %d of %q", "upstreams", item, recordKind, index, arrayField)
				return checkNameStringEncoding(dec, location)
			})
		}},
	}
}

// scanNameUpstreamsRecords validates every record of a "name" + "upstreams"
// array: datasets in a graph (arrayField "datasets", recordKind "dataset
// record") or changes in a plan ("changes", "change record"). The decoder
// must be positioned at the field's array value.
func scanNameUpstreamsRecords(dec *json.Decoder, arrayField, recordKind string) error {
	return checkArrayElements(dec, func(dec *json.Decoder, index int) error {
		return scanObjectFields(dec, graphNameFields(index, arrayField, recordKind))
	})
}

// scanRemovalsNames validates every element of a plan's "removals" array.
// A removal is a lineage name even when the dataset it names does not
// exist, so its raw literal is checked like every other name. The decoder
// must be positioned at the field's array value.
func scanRemovalsNames(dec *json.Decoder) error {
	return checkArrayElements(dec, func(dec *json.Decoder, index int) error {
		location := fmt.Sprintf("field %q at index %d", "removals", index)
		return checkNameStringEncoding(dec, location)
	})
}

// checkNameStringEncoding consumes one value and, when it is a string
// literal, validates its raw bytes with validateNameStringLiteral. A
// non-string value is skipped: the regular parse reports the type error.
func checkNameStringEncoding(dec *json.Decoder, location string) error {
	var raw json.RawMessage
	if err := dec.Decode(&raw); err != nil {
		return errAbortScan
	}
	if len(raw) < 2 || raw[0] != '"' {
		return nil
	}
	return validateNameStringLiteral(raw, location)
}

// validateNameStringLiteral checks one raw JSON string literal (surrounding
// quotes included) for the two corruptions the decoder would silently
// rewrite to U+FFFD: bytes that are not valid UTF-8, and \u escapes forming
// an unpaired surrogate. The literal is known to be syntactically valid
// JSON (the regular parse already accepted the document), so escapes are
// well-formed; anything else unexpected aborts the scan and is left to that
// parse. location identifies the field and position in the error.
func validateNameStringLiteral(raw []byte, location string) error {
	end := len(raw) - 1 // index of the closing quote
	for i := 1; i < end; {
		c := raw[i]
		switch {
		case c == '\\':
			if i+1 >= end {
				return errAbortScan
			}
			if raw[i+1] != 'u' {
				i += 2 // \", \\, \/, \b, \f, \n, \r, \t
				continue
			}
			if i+6 > end {
				return errAbortScan
			}
			cp, ok := hex4(raw[i+2 : i+6])
			if !ok {
				return errAbortScan
			}
			i += 6
			switch {
			case isHighSurrogate(cp):
				// A high surrogate is legal only as the first half of a
				// pair: the very next escape must be its low surrogate.
				if i+6 <= end && raw[i] == '\\' && raw[i+1] == 'u' {
					if low, ok := hex4(raw[i+2 : i+6]); ok && isLowSurrogate(low) {
						i += 6
						continue
					}
				}
				return unpairedSurrogateError(location)
			case isLowSurrogate(cp):
				// A lone low surrogate — including one written before its
				// high surrogate — never forms a pair.
				return unpairedSurrogateError(location)
			}
		case c < utf8.RuneSelf:
			i++
		default:
			// A genuine U+FFFD decodes with size 3 and is accepted; only a
			// byte the decoder cannot map (size 1) is corruption.
			r, size := utf8.DecodeRune(raw[i:end])
			if r == utf8.RuneError && size == 1 {
				return invalidUTF8BytesError(location)
			}
			i += size
		}
	}
	return nil
}

// hex4 parses exactly four hexadecimal digits (one \u escape unit).
func hex4(b []byte) (rune, bool) {
	var v rune
	for _, c := range b {
		v <<= 4
		switch {
		case c >= '0' && c <= '9':
			v |= rune(c - '0')
		case c >= 'a' && c <= 'f':
			v |= rune(c-'a') + 10
		case c >= 'A' && c <= 'F':
			v |= rune(c-'A') + 10
		default:
			return 0, false
		}
	}
	return v, true
}

func isHighSurrogate(cp rune) bool { return cp >= 0xD800 && cp <= 0xDBFF }
func isLowSurrogate(cp rune) bool  { return cp >= 0xDC00 && cp <= 0xDFFF }

// invalidUTF8BytesError reports a name whose raw string literal carries
// bytes that are not valid UTF-8.
func invalidUTF8BytesError(location string) error {
	return fmt.Errorf("%w: %s contains invalid UTF-8 bytes", ErrInvalidArgument, location)
}

// unpairedSurrogateError reports a name whose \u escapes form an unpaired
// surrogate (a lone high or low surrogate, or a low surrogate before its
// high surrogate).
func unpairedSurrogateError(location string) error {
	return fmt.Errorf("%w: %s contains an unpaired surrogate escape", ErrInvalidArgument, location)
}

// Package chainledger applies the shared raw name-encoding rule (see
// name_encoding.go) to a graph object, whether it stands alone as a graph
// file or is embedded as a snapshot's "graph" value.
//
// Every name a graph carries — each datasets[i].name and every
// datasets[i].upstreams[j] — is checked against its RAW string literal
// before the graph is accepted. A literal carrying bytes that are not valid
// UTF-8, or a \u escape forming an unpaired surrogate (a lone high or low
// surrogate, or a low surrogate written before its high surrogate), rejects
// the whole input: the decoder's U+FFFD rewrite is never kept, the offending
// node or edge is never skipped, and a snapshot whose declared content
// identifier happens to equal the rewritten graph's digest is still refused.
//
// Field recognition, record reading, unknown-field skipping, locations, and
// the byte-vs-surrogate error wording are the shared machinery in
// name_encoding.go and duplicate_fields.go, so a standalone graph file and
// an embedded snapshot graph are judged by exactly the same code.
package chainledger

import (
	"encoding/json"
)

// checkGraphNameEncoding scans the raw JSON of one graph object — either the
// whole of a standalone graph file or the "graph" value embedded in a
// snapshot — and rejects the entire document when any dataset name or direct
// upstream reference is written with a string literal the decoder cannot
// read faithfully (invalid UTF-8 bytes or an unpaired surrogate escape).
// The error names the field and the zero-based dataset record position, and
// for an upstream the zero-based array position too, and says which of the
// two corruptions occurred.
func checkGraphNameEncoding(data []byte) error {
	return runFieldScan(data, func(dec *json.Decoder) error {
		return scanObjectFields(dec, []knownField{
			{name: "datasets", nested: func(dec *json.Decoder) error {
				return scanNameUpstreamsRecords(dec, "datasets", "dataset record")
			}},
		})
	})
}

