57	// combination of {big-number placement} x {corrupt business name} through
58	// BOTH preview and apply, and requires the identical name-encoding failure
59	// from each: non-zero exit, no report on stdout, and a precise stderr.
60	func TestCLIBigNumberUnknownFieldsDoNotMaskCorruptNames(t *testing.T) {
61		bigPrefixes := map[string]string{
62			"big number opens the plan":           `{"note":1e400,`,
63			"big number nested before changes":    `{"meta":{"x":[1e400,{"y":1e999}]},`,
64			"big numbers in an unknown array":     `{"bag":[1e400,"z",[2e999,{"k":-1e400}]],`,
65			"big unknown field inside the record": `{"changes":[{`,
66		}
67	
68		cases := map[string]struct {
69			// plan renders the corrupt plan with a given prefix placement.
70			plan     func(prefix string) string
71			field    string
72			location string
73			reason   string
74		}{
75			"invalid bytes in change name": {
76				func(p string) string {
77					if strings.HasPrefix(p, `{"changes":[{`) {
78						return p + `"note":1e400,"name":"a` + "\xff" + `","upstreams":[]}]}`
79					}
80					return p + `"changes":[{"name":"a` + "\xff" + `","upstreams":[]}]}`
81				},
82				`"name"`, `index 0 of "changes"`, "invalid UTF-8 bytes",
83			},
84			"unpaired surrogate in change name": {
85				func(p string) string {
86					if strings.HasPrefix(p, `{"changes":[{`) {
87						return p + `"note":[1e999],"name":"a\ud800","upstreams":[]}]}`
88					}
89					return p + `"changes":[{"name":"a\ud800","upstreams":[]}]}`
90				},
91				`"name"`, `index 0 of "changes"`, "unpaired surrogate",
92			},
93			"invalid bytes in an upstream entry": {
94				// The array position of the upstream entry must be reported, and
95				// the failure is the corrupt name — never a missing upstream.
96				func(p string) string {
97					if strings.HasPrefix(p, `{"changes":[{`) {
98						return p + `"name":"A","note":1e400,"upstreams":["ok","g` + "\xfe" + `"]}]}`
99					}
100					return p + `"changes":[{"name":"A","upstreams":["ok","g` + "\xfe" + `"]}]}`
101				},
102				`"upstreams"`, `index 1`, "invalid UTF-8 bytes",
103			},
104			"unpaired surrogate in an upstream entry": {
105				func(p string) string {
106					if strings.HasPrefix(p, `{"changes":[{`) {
107						return p + `"name":"A","meta":[1e400],"upstreams":["\udfff"]}]}`
108					}
109					return p + `"changes":[{"name":"A","upstreams":["\udfff"]}]}`
110				},
111				`"upstreams"`, `index 0`, "unpaired surrogate",
112			},
113			"invalid bytes in a removals entry": {
114				func(p string) string {
115					if strings.HasPrefix(p, `{"changes":[{`) {
116						// The big number lives in a legal change record that
117						// precedes the corrupt removals array.
118						return p + `"name":"A","note":1e400,"upstreams":[]}],"removals":["ok","b","c` + "\xc3" + `"]}`
119					}
120					return p + `"removals":["ok","b","c` + "\xc3" + `"]}`
121				},
122				`"removals"`, `index 2`, "invalid UTF-8 bytes",
123			},
124			"unpaired surrogate in a removals entry": {
125				func(p string) string {
126					if strings.HasPrefix(p, `{"changes":[{`) {
127						return p + `"name":"A","note":[1e999],"upstreams":[]}],"removals":["ok","\udc00\ud800"]}`
128					}
129					return p + `"removals":["ok","\udc00\ud800"]}`
130				},
131				`"removals"`, `index 1`, "unpaired surrogate",
132			},
133		}
134	
135		for prefixName, prefix := range bigPrefixes {
136			for caseName, tc := range cases {
137				t.Run(prefixName+" / "+caseName, func(t *testing.T) {
138					planContent := tc.plan(prefix)
139					for _, verb := range []string{"preview", "apply"} {
140						t.Run(verb, func(t *testing.T) {
141							graphPath := writeFile(t, "graph.json",
142								`{"datasets":[{"name":"A","upstreams":[]},{"name":"ok","upstreams":["A"]}]}`)
143							planPath := writeFile(t, "plan.json", planContent)
144							graphBefore := readFile(t, graphPath)
145							planBefore := readFile(t, planPath)
146	
147							stdout, stderr, exit := runBatchCLI(t, verb, graphPath, planPath)
148							if exit == 0 {
149								t.Fatalf("%s exit = 0, want non-zero; stdout = %s", verb, stdout)
150							}
151							if stdout != "" {
152								t.Errorf("%s stdout = %q, want empty on rejection", verb, stdout)
153							}
154							if !strings.Contains(stderr, planPath) {
155								t.Errorf("stderr = %q, want it to name the plan file %q", stderr, planPath)
156							}
157							for _, want := range []string{tc.field, tc.location, tc.reason} {
158								if !strings.Contains(stderr, want) {
159									t.Errorf("stderr = %q, want it to contain %q", stderr, want)
160								}
161							}
162							switch tc.reason {
163							case "invalid UTF-8 bytes":
164								if strings.Contains(stderr, "surrogate") {
165									t.Errorf("stderr = %q, byte corruption must not read as a surrogate problem", stderr)
166								}
167							case "unpaired surrogate":
168								if strings.Contains(stderr, "invalid UTF-8 bytes") {
169									t.Errorf("stderr = %q, a surrogate problem must not read as invalid bytes", stderr)
170								}
171							}
172							// Neither file may change: a rejected apply writes no
173							// graph, and the plan is only ever read.
174							if got := readFile(t, graphPath); got != graphBefore {
175								t.Errorf("graph file changed after rejected %s:\n got %s\nwant %s", verb, got, graphBefore)
176							}
177							if got := readFile(t, planPath); got != planBefore {
178								t.Errorf("plan file changed after rejected %s", verb)
179							}
180						})
181					}
182				})
183			}
184		}
185	}
186	
187	// TestCLICorruptRemovalKeepsRealReplacementCharDataset: the graph really
188	// contains a dataset named "源�". A removal written as "源" plus a broken
189	// byte or a lone surrogate — preceded by big-number additions that must be
190	// ignored — cannot delete it through the decoder's U+FFFD rewrite, and a
191	// corrupted name matching no dataset at all cannot pass as the no-op
192	// "remove a nonexistent name". Both files keep their original bytes after
193	// preview and after apply.
194	func TestCLICorruptRemovalKeepsRealReplacementCharDataset(t *testing.T) {
195		cases := map[string]struct {
196			plan   string
197			reason string
198		}{
199			"broken byte would collide with real 源�": {
200				`{"note":1e400,"removals":["源` + "\xff" + `"]}`, "invalid UTF-8 bytes",
201			},
202			"lone surrogate would collide with real 源�": {
203				`{"meta":[1e999,{"z":-1e400}],"removals":["源\ud800"]}`, "unpaired surrogate",
204			},
205			"low-before-high surrogate would collide": {
206				`{"note":{"x":1e400},"removals":["源\udc00\ud800"]}`, "unpaired surrogate",
207			},
208			"broken byte names no dataset": {
209				`{"note":1e400,"removals":["ghost` + "\xff" + `"]}`, "invalid UTF-8 bytes",
210			},
211			"lone surrogate names no dataset": {
212				`{"bag":[1e400],"removals":["ghost\udfff"]}`, "unpaired surrogate",
213			},
214		}
215		for name, tc := range cases {
216			t.Run(name, func(t *testing.T) {
217				for _, verb := range []string{"preview", "apply"} {
218					t.Run(verb, func(t *testing.T) {
219						graphPath := writeFile(t, "graph.json", graphWithReplacementCharRoot)
220						planPath := writeFile(t, "plan.json", tc.plan)
221						graphBefore := readFile(t, graphPath)
222						planBefore := readFile(t, planPath)
223	
224						stdout, stderr, exit := runBatchCLI(t, verb, graphPath, planPath)
225						if exit == 0 {
226							t.Fatalf("%s exit = 0, want non-zero; stdout = %s", verb, stdout)
227						}
228						if stdout != "" {
229							t.Errorf("%s stdout = %q, want empty on rejection", verb, stdout)
230						}
231						for _, want := range []string{planPath, `"removals"`, "index 0", tc.reason} {
232							if !strings.Contains(stderr, want) {
233								t.Errorf("stderr = %q, want it to contain %q", stderr, want)
234							}
235						}
236						if strings.Contains(stderr, "no change") {
237							t.Errorf("stderr = %q, a corrupt name must not pass as a no-change success", stderr)
238						}
239						if got := readFile(t, graphPath); got != graphBefore {
240							t.Errorf("graph file changed:\n got %s\nwant %s", got, graphBefore)
241						}
242						if got := readFile(t, planPath); got != planBefore {
243							t.Errorf("plan file changed")
244						}
245						graph := mustReadGraphCLI(t, graphPath)
246						if _, ok := graph["源�"]; !ok {
247							t.Fatal("the dataset really named 源� was deleted by a corrupted removal")
248						}
249						if _, ok := graph["keep"]; !ok {
250							t.Fatal("the unrelated dataset keep disappeared")
251						}
252					})
253				}
254			})
255		}
256	}
257	
258	// TestCLIBigNumbersWholeBatchRejectedBeforeAnyChange: with a big number in
259	// an ignored field, a legal adjustment that WOULD change the graph, and a
260	// corrupt removal later in the same plan, apply must reject the whole batch
261	// — the legal adjustment must not take effect either, and the real "源�"
262	// must survive. Preview behaves identically and touches neither file.
263	func TestCLIBigNumbersWholeBatchRejectedBeforeAnyChange(t *testing.T) {
264		// down really depends on 源�; the legal change would clear that edge.
265		graphContent := `{"datasets":[{"name":"源�","upstreams":[]},{"name":"down","upstreams":["源�"]}]}`
266		for _, corrupt := range []struct {
267			name    string
268			removal string
269			reason  string
270		}{
271			{"broken byte", `"源` + "\xff" + `"`, "invalid UTF-8 bytes"},
272			{"lone surrogate", `"源\ud800"`, "unpaired surrogate"},
273		} {
274			t.Run(corrupt.name, func(t *testing.T) {
275				planContent := `{"note":1e400,"changes":[{"name":"down","upstreams":[],"meta":[1e999]}],` +
276					`"removals":[` + corrupt.removal + `]}`
277				for _, verb := range []string{"preview", "apply"} {
278					t.Run(verb, func(t *testing.T) {
279						graphPath := writeFile(t, "graph.json", graphContent)
280						planPath := writeFile(t, "plan.json", planContent)
281						graphBefore := readFile(t, graphPath)
282	
283						stdout, stderr, exit := runBatchCLI(t, verb, graphPath, planPath)
284						if exit == 0 {
285							t.Fatalf("%s exit = 0, want non-zero; stdout = %s", verb, stdout)
286						}
287						if stdout != "" {
288							t.Errorf("%s stdout = %q, want empty", verb, stdout)
289						}
290						for _, want := range []string{planPath, `"removals"`, "index 0", corrupt.reason} {
291							if !strings.Contains(stderr, want) {
292								t.Errorf("stderr = %q, want it to contain %q", stderr, want)
293							}
294						}
295						// Graph bytes unchanged: neither the legal change nor the
296						// corrupted removal took effect.
297						if got := readFile(t, graphPath); got != graphBefore {
298							t.Errorf("graph file changed after rejected %s:\n got %s\nwant %s", verb, got, graphBefore)
299						}
300						graph := mustReadGraphCLI(t, graphPath)
301						if _, ok := graph["源�"]; !ok {
302							t.Fatal("the dataset really named 源� must survive")
303						}
304						if parents := graph["down"].Parents; len(parents) != 1 || parents[0] != "源�" {
305							t.Fatalf("down.Parents = %v, the legal change must not have taken effect, want [源�]", parents)
306						}
307					})
308				}
309			})
310		}
311	}
312	
313	// TestCLILegalRemovalOfReplacementCharWithBigNumbers: once the removal
314	// really names "源�" — written directly or with equivalent JSON escapes —
315	// and carries the same big-number additions, preview and apply succeed: the
316	// real name shows up in removedDatasets, and apply leaves exactly the
317	// surviving graph on disk.
318	func TestCLILegalRemovalOfReplacementCharWithBigNumbers(t *testing.T) {
319		direct := `{"note":1e400,"meta":[1e999,{"z":-1e400}],"removals":["源�"]}`
320		escaped := `{"note":1e400,"meta":[1e999,{"z":-1e400}],"removals":["\u6e90\ufffd"]}`
321		if direct == escaped {
322			t.Fatal("test premise broken: the two spellings must differ on disk")
323		}
324		for name, planContent := range map[string]string{"direct": direct, "escaped": escaped} {
325			t.Run(name, func(t *testing.T) {
326				// Preview first: report carries the real removal, graph untouched.
327				previewGraph := writeFile(t, "graph-preview.json", graphWithReplacementCharRoot)
328				planPath := writeFile(t, "plan.json", planContent)
329				graphBefore := readFile(t, previewGraph)
330				stdout, stderr, exit := runBatchCLI(t, "preview", previewGraph, planPath)
331				if exit != 0 {
332					t.Fatalf("preview exit = %d, stderr = %s", exit, stderr)
333				}
334				if got := mustParseReport(t, stdout).RemovedDatasets; len(got) != 1 || got[0] != "源�" {
335					t.Errorf("preview removedDatasets = %v, want [源�]", got)
336				}
337				if got := readFile(t, previewGraph); got != graphBefore {
338					t.Errorf("preview changed the graph file")
339				}
340	
341				// Apply: the real dataset is removed, keep survives, and applying
342				// the same plan once more is still a successful no-op.
343				applyGraph := writeFile(t, "graph-apply.json", graphWithReplacementCharRoot)
344				stdout, stderr, exit = runBatchCLI(t, "apply", applyGraph, planPath)
345				if exit != 0 {
346					t.Fatalf("apply exit = %d, stderr = %s", exit, stderr)
347				}
348				if got := mustParseReport(t, stdout).RemovedDatasets; len(got) != 1 || got[0] != "源�" {
349					t.Errorf("apply removedDatasets = %v, want [源�]", got)
350				}
351				graph := mustReadGraphCLI(t, applyGraph)
352				if _, ok := graph["源�"]; ok {
353					t.Fatal("the dataset really named 源� must be gone after apply")
354				}
355				if _, ok := graph["keep"]; !ok {
356					t.Fatal("the unrelated dataset keep must survive")
357				}
358	
359				stdout, stderr, exit = runBatchCLI(t, "apply", applyGraph, planPath)
360				if exit != 0 {
361					t.Fatalf("re-apply exit = %d, stderr = %s", exit, stderr)
362				}
363				if got := mustParseReport(t, stdout).RemovedDatasets; len(got) != 0 {
364					t.Errorf("re-apply must report no removals, got %v", got)
365				}
366			})
367		}
368	}
369	
370	// TestCLIUnknownFieldsDoNotChangeReportOrGraph: for a plan whose business
371	// names are all legal, adding or removing the additional information
372	// (oversized numbers at the top level, nested in unknown objects/arrays, or
373	// inside change records) changes neither preview's report bytes nor apply's
374	// report bytes and the final graph file.
375	func TestCLIUnknownFieldsDoNotChangeReportOrGraph(t *testing.T) {
376		graphContent := `{"datasets":[{"name":"A","upstreams":[]},{"name":"B","upstreams":["A"]},{"name":"源�","upstreams":[]}]}`
377		plans := map[string]string{
378			"plain": `{"changes":[{"name":"B","upstreams":["源�"]}],"removals":["A"]}`,
379			"big number at top": `{"note":1e400,` +
380				`"changes":[{"name":"B","upstreams":["源�"]}],"removals":["A"]}`,
381			"big numbers nested everywhere": `{"meta":{"x":[1e400,{"y":1e999}]},"changes":[` +
382				`{"name":"B","upstreams":["源�"],"vals":[1e999,-1e400],"note":{}}],` +
383				`"removals":["A"],"tail":[2e400]}`,
384		}
385	
386		// Preview reports must be byte-identical across the plan spellings.
387		var basePreview string
388		for name, planContent := range plans {
389			graphPath := writeFile(t, filepath.Join(name+"-preview-graph.json"), graphContent)
390			planPath := writeFile(t, filepath.Join(name+"-plan.json"), planContent)
391			stdout, stderr, exit := runBatchCLI(t, "preview", graphPath, planPath)
392			if exit != 0 {
393				t.Fatalf("preview %s exit = %d, stderr = %s", name, exit, stderr)
394			}
395			if basePreview == "" {
396				basePreview = stdout
397			} else if stdout != basePreview {
398				t.Fatalf("preview %s report differs from plain:\n%s\n%s", name, stdout, basePreview)
399			}
400		}
401	
402		// Apply: identical reports and identical resulting graph bytes.
403		var baseApply, baseGraph string
404		for name, planContent := range plans {
405			graphPath := writeFile(t, filepath.Join(name+"-apply-graph.json"), graphContent)
406			planPath := writeFile(t, filepath.Join(name+"-apply-plan.json"), planContent)
407			stdout, stderr, exit := runBatchCLI(t, "apply", graphPath, planPath)
408			if exit != 0 {
409				t.Fatalf("apply %s exit = %d, stderr = %s", name, exit, stderr)
410			}
411			finalGraph := readFile(t, graphPath)
412			if baseApply == "" {
413				baseApply, baseGraph = stdout, finalGraph
414			} else {
415				if stdout != baseApply {
416					t.Fatalf("apply %s report differs from plain:\n%s\n%s", name, stdout, baseApply)
417				}
418				if finalGraph != baseGraph {
419					t.Fatalf("apply %s graph bytes differ from plain:\n%s\n%s", name, finalGraph, baseGraph)
420				}
421			}
422		}
423	}
