15	// traceGraph is a diamond with a direct shortcut: T reaches R directly, via
16	// B, and via A; it also reaches root Z via A. S is disconnected.
17	const traceGraph = `{"datasets":[
18		{"name":"T","upstreams":["R","B","A"]},
19		{"name":"A","upstreams":["R","Z"]},
20		{"name":"B","upstreams":["R"]},
21		{"name":"R","upstreams":[]},
22		{"name":"Z","upstreams":[]},
23		{"name":"S","upstreams":[]}
24	]}`
25	
26	// snapshotForTrace writes graphJSON to a graph file, snapshots it, and
27	// returns the snapshot path.
28	func snapshotForTrace(t *testing.T, graphJSON string) string {
29		t.Helper()
30		dir := t.TempDir()
31		graphPath := filepath.Join(dir, "graph.json")
32		if err := os.WriteFile(graphPath, []byte(graphJSON), 0o644); err != nil {
33			t.Fatalf("write graph: %v", err)
34		}
35		snapPath := filepath.Join(dir, "snap.json")
36		if _, stderr, exit := captureStdout(t, func() int {
37			return run([]string{"snapshot", graphPath, snapPath})
38		}); exit != 0 {
39			t.Fatalf("snapshot exit = %d, stderr = %s", exit, stderr)
40		}
41		return snapPath
42	}
