44	func TestCLITraceProducesReport(t *testing.T) {
45		snapPath := snapshotForTrace(t, traceGraph)
46		snapBytes := readFile(t, snapPath)
47		before := dirNames(t, filepath.Dir(snapPath))
48	
49		stdout, stderr, exit := captureStdout(t, func() int {
50			return run([]string{"trace", snapPath, "T"})
51		})
52		if exit != 0 {
53			t.Fatalf("trace exit = %d, stderr = %s", exit, stderr)
54		}
55		var report chainledger.TraceReport
56		if err := json.Unmarshal([]byte(stdout), &report); err != nil {
57			t.Fatalf("trace stdout is not valid JSON: %v\n%s", err, stdout)
58		}
59		if report.Dataset != "T" {
60			t.Errorf("Dataset = %q, want %q", report.Dataset, "T")
61		}
62		snap, err := chainledger.ParseSnapshot([]byte(snapBytes))
63		if err != nil {
64			t.Fatalf("parse snapshot: %v", err)
65		}
66		if report.ContentID != snap.ContentID {
67			t.Errorf("ContentID = %q, want %q", report.ContentID, snap.ContentID)
68		}
69		want := []chainledger.SourceTrace{
70			{Root: "R", Path: []string{"T", "R"}},
71			{Root: "Z", Path: []string{"T", "A", "Z"}},
72		}
73		if !reflect.DeepEqual(report.Sources, want) {
74			t.Errorf("Sources = %+v, want %+v", report.Sources, want)
75		}
76	
77		// trace is read-only: the snapshot keeps every byte and no lock file or
78		// other sibling is created.
79		if got := readFile(t, snapPath); got != snapBytes {
