270		}
271	
272		for name, data := range map[string][]byte{"direct": direct, "escaped": escaped} {
273			t.Run(name, func(t *testing.T) {
274				graph := buildGraph(t, P("源�"), P("keep"))
275				plan, err := UnmarshalPlan(data)
276				if err != nil {
277					t.Fatalf("UnmarshalPlan: %v", err)
278				}
279				report, err := PreviewBatch(graph, plan)
