369			t.Run("surrogate/"+name, func(t *testing.T) {
370				_, err := ParseSnapshot(snapshotEnvelope(bogusID, tc.data))
371				assertCorruptNameError(t, err, tc.field, tc.location, "unpaired surrogate")
372			})
373		}
374	}
375	
376	// TestParseSnapshotCorruptNameRejectedEvenWhenContentIDMatches: even a
377	// snapshot whose declared content identifier is the genuine identifier of
378	// the graph AS REWRITTEN by the decoder (the root genuinely named "源�" and
379	// an edge the rewrite makes resolve to it) must be refused for the corrupt
380	// name, rather than accepted because the digests line up.
381	func TestParseSnapshotCorruptNameRejectedEvenWhenContentIDMatches(t *testing.T) {
382		// Build the product-computed identifier of the post-rewrite graph.
383		rewritten := `{"datasets":[{"name":"源�","upstreams":[]},{"name":"d","upstreams":["源�"]}]}`
384		graph, err := UnmarshalGraphFile([]byte(rewritten))
385		if err != nil {
386			t.Fatalf("UnmarshalGraphFile rewritten: %v", err)
387		}
388		snap, err := BuildSnapshot(graph)
389		if err != nil {
390			t.Fatalf("BuildSnapshot: %v", err)
391		}
392		corruptGraph := `{"datasets":[{"name":"源�","upstreams":[]},{"name":"d","upstreams":["源\uD800"]}]}`
393		if _, err := ParseSnapshot(snapshotEnvelope(snap.ContentID, corruptGraph)); err == nil {
394			t.Fatal("snapshot accepted a corrupt-name graph whose rewritten digest matches the declared id")
395		}
396		// The equivalent clean document parses under that same identifier,
397		// proving the identifier really did match the rewritten graph.
398		valid, err := ParseSnapshot(snapshotEnvelope(snap.ContentID, rewritten))
399		if err != nil {
400			t.Fatalf("the equivalent clean snapshot must still parse: %v", err)
401		}
402		if valid.ContentID != snap.ContentID {
403			t.Errorf("content id = %q, want %q", valid.ContentID, snap.ContentID)
404		}
405	}
406	
407	// TestParseSnapshotAcceptsGenuineUnicodeGraphNames: a frozen graph keeps
408	// genuine replacement characters, paired surrogate escapes, CJK and emoji
409	// names, and corrupt strings confined to unknown fields do not count.
410	func TestParseSnapshotAcceptsGenuineUnicodeGraphNames(t *testing.T) {
411		graphJSON := `{"datasets":[{"name":"源�","upstreams":[]},{"name":"ledger😀","upstreams":["源�"]}]}`
412		graph, err := UnmarshalGraphFile([]byte(graphJSON))
413		if err != nil {
414			t.Fatalf("UnmarshalGraphFile: %v", err)
415		}
416		snap, err := BuildSnapshot(graph)
417		if err != nil {
418			t.Fatalf("BuildSnapshot: %v", err)
419		}
420		data, err := MarshalSnapshot(snap)
421		if err != nil {
422			t.Fatalf("MarshalSnapshot: %v", err)
423		}
424		parsed, err := ParseSnapshot(data)
425		if err != nil {
426			t.Fatalf("ParseSnapshot rejected legal Unicode graph names: %v", err)
427		}
428		var foundEmoji bool
429		for _, ds := range parsed.Graph.Datasets {
430			if ds.Name == "ledger😀" {
431				foundEmoji = true
432				if !reflect.DeepEqual(ds.Upstreams, []string{"源�"}) {
433					t.Errorf("upstreams = %v, want [源�]", ds.Upstreams)
434				}
435			}
436		}
437		if !foundEmoji {
438			t.Errorf("snapshot lost the emoji dataset: %+v", parsed.Graph.Datasets)
439		}
440	
441		// Corrupt strings confined to unknown fields do not reject the snapshot.
442		legalWithUnknown := []byte(`{"formatVersion":1,"contentId":"` + snap.ContentID + `","note":"a\ud800",` +
443			`"graph":{"meta":["x` + "\xff" + `"],"datasets":[{"name":"源�","upstreams":[]},{"name":"ledger😀","upstreams":["源�"]}]}}`)
444		if _, err := ParseSnapshot(legalWithUnknown); err != nil {
445			t.Errorf("unknown-field strings must not trigger the name check: %v", err)
446		}
447	}
