			t.Fatalf("%s: %v", name, err)
		}
		if p.ContentID != id {
			t.Errorf("%s: id changed", name)
		}
		r, err := TraceSources(p, "B")
		if err != nil {
			t.Fatalf("%s trace: %v", name, err)
		}
		b, _ := json.Marshal(r)
		out := string(b)
		if base == "" {
			base = out
		} else if out != base {
			t.Errorf("%s trace differs:\n%s\n%s", name, out, base)
		}
	}

	g2, err := UnmarshalGraphFile([]byte(`{"datasets":[{"name":"x\\ud800","upstreams":[]},{"name":"y","upstreams":["x\\ud800"]}]}`))
	if err != nil {
		t.Fatal(err)
	}
	s2, _ := BuildSnapshot(g2)
	lb := `{"note":1e400,"formatVersion":1,"contentId":"` + s2.ContentID +
		`","graph":{"datasets":[{"name":"x\\ud800","upstreams":[]},{"note":1e400,"name":"y","upstreams":["x\\ud800"]}]}}`
	p, err := ParseSnapshot([]byte(lb))
	if err != nil {
		t.Fatalf("backslash lookalike rejected: %v", err)
	}
	r, err := TraceSources(p, "y")
	if err != nil {
		t.Fatal(err)
	}
	if len(r.Sources) != 1 || r.Sources[0].Root != `x\ud800` {
		t.Errorf("root = %+v", r.Sources)
	}
}

