60	func readAll(f *os.File) ([]byte, error) {
61		var out []byte
62		buf := make([]byte, 4096)
63		for {
64			n, err := f.Read(buf)
65			out = append(out, buf[:n]...)
66			if err != nil {
67				break
68			}
69		}
70		return out, nil
71	}
